<?php
declare(strict_types=1);
ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');
session_start();date_default_timezone_set('Asia/Tehran');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);}catch(Throwable $e){exit('اتصال برقرار نیست.');}
$me=ts_require_roles($pdo,['owner']);
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('درخواست نامعتبر');}
 $a=(string)($_POST['action']??'');
 try{
  if($a==='create'){
   $username=trim((string)($_POST['username']??''));$display=trim((string)($_POST['display_name']??''));$role=(string)($_POST['role']??'staff');$pass=(string)($_POST['password']??'');
   if(!preg_match('/^[A-Za-z0-9_.-]{3,80}$/',$username))throw new RuntimeException('نام کاربری باید حداقل ۳ کاراکتر و فقط شامل حروف انگلیسی، عدد، نقطه، خط تیره یا زیرخط باشد.');
   if(!in_array($role,ts_roles(),true))throw new RuntimeException('نقش نامعتبر است.');
   if(strlen($pass)<12)throw new RuntimeException('رمز عبور حداقل ۱۲ کاراکتر باشد.');
   $s=$pdo->prepare('INSERT INTO admins(username,display_name,password_hash,role,active,failed_attempts,password_changed_at,created_at) VALUES(?,?,?,?,1,0,NOW(),NOW())');$s->execute([$username,$display?:null,password_hash($pass,PASSWORD_DEFAULT),$role]);
   ts_audit($pdo,'admin_created',$username.' / '.$role);$msg='کاربر جدید ساخته شد.';
  }
  if($a==='update'){
   $id=max(0,(int)($_POST['id']??0));$display=trim((string)($_POST['display_name']??''));$role=(string)($_POST['role']??'staff');$active=isset($_POST['active'])?1:0;
   if(!$id||!in_array($role,ts_roles(),true))throw new RuntimeException('اطلاعات نامعتبر است.');
   $s=$pdo->prepare('SELECT id,username,role,active FROM admins WHERE id=?');$s->execute([$id]);$u=$s->fetch();if(!$u)throw new RuntimeException('کاربر پیدا نشد.');
   if($id===(int)$me['id']&&($role!=='owner'||!$active))throw new RuntimeException('برای جلوگیری از قفل‌شدن مدیریت، حساب خودتان را غیرفعال یا از مدیر کل خارج نکنید.');
   if((string)$u['role']==='owner'&&((!$active)||$role!=='owner')){$owners=(int)$pdo->query("SELECT COUNT(*) FROM admins WHERE role='owner' AND active=1")->fetchColumn();if($owners<=1)throw new RuntimeException('حداقل یک مدیر کل فعال باید باقی بماند.');}
   $q=$pdo->prepare('UPDATE admins SET display_name=?,role=?,active=? WHERE id=?');$q->execute([$display?:null,$role,$active,$id]);ts_audit($pdo,'admin_updated',(string)$u['username'].' / '.$role.' / active='.$active);$msg='دسترسی کاربر ذخیره شد.';
  }
  if($a==='password'){
   $id=max(0,(int)($_POST['id']??0));$pass=(string)($_POST['password']??'');if(strlen($pass)<12)throw new RuntimeException('رمز جدید حداقل ۱۲ کاراکتر باشد.');
   $s=$pdo->prepare('SELECT username FROM admins WHERE id=?');$s->execute([$id]);$username=(string)($s->fetchColumn()?:'');if($username==='')throw new RuntimeException('کاربر پیدا نشد.');
   $q=$pdo->prepare('UPDATE admins SET password_hash=?,failed_attempts=0,locked_until=NULL,password_changed_at=NOW() WHERE id=?');$q->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);ts_audit($pdo,'password_reset',$username);$msg='رمز عبور تغییر کرد و قفل ورود نیز پاک شد.';
  }
 }catch(Throwable $x){$err=$x->getMessage();}
}
$users=$pdo->query('SELECT id,username,display_name,role,active,failed_attempts,locked_until,last_login_at,last_login_ip,created_at FROM admins ORDER BY id')->fetchAll();
$logs=$pdo->query('SELECT username,action,details,ip,created_at FROM admin_audit_log ORDER BY id DESC LIMIT 30')->fetchAll();
$statusFile=__DIR__.'/storage/backups/backup-status.json';$backup=null;if(is_file($statusFile)){$j=json_decode((string)@file_get_contents($statusFile),true);if(is_array($j))$backup=$j;}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>امنیت و کاربران | سوپرمارکت طهران</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1050px;margin:20px auto;padding:0 12px}.user{background:#fff;border:1px solid #e4ebe5;border-radius:16px;padding:14px;margin:10px 0}.usergrid{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;gap:8px;align-items:end}.tag{display:inline-block;padding:3px 8px;border-radius:99px;background:#eef6ef;font-size:11px}.dangertext{color:#a52e26}.logs{overflow:auto}.logs table{width:100%;border-collapse:collapse}.logs th,.logs td{padding:8px;border-bottom:1px solid #edf1ee;text-align:right;white-space:nowrap;font-size:12px}@media(max-width:700px){.usergrid{grid-template-columns:1fr 1fr}.usergrid .wide{grid-column:1/-1}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">🔐</span><span><b>امنیت و کاربران</b><small>نقش‌ها، ورود و بکاپ</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><section class="panel"><h2>+ ساخت کاربر</h2><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="create"><label>نام نمایشی<input name="display_name" placeholder="مثلاً صندوقدار صبح"></label><label>نام کاربری<input name="username" required autocomplete="off"></label><label>نقش<select name="role"><option value="staff">کارمند سفارش</option><option value="manager">مدیر فروشگاه</option><option value="owner">مدیر کل</option></select></label><label>رمز اولیه<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><button class="btn wide">ساخت حساب</button></form><p class="muted">کارمند سفارش فقط به جمع‌آوری و وضعیت سفارش‌ها دسترسی دارد؛ مدیر فروشگاه به کالاها، قیمت، تخفیف و تنظیمات عملیاتی؛ مدیر کل به همه بخش‌ها و کاربران.</p></section><section class="panel"><h2>کاربران مدیریت</h2><?php foreach($users as $u):?><div class="user"><div><b><?=e($u['display_name']?:$u['username'])?></b> <span class="tag"><?=e(ts_role_label((string)$u['role']))?></span> <?=$u['active']?'':'<span class="dangertext">غیرفعال</span>'?><div class="muted">@<?=e($u['username'])?> · آخرین ورود: <?=e($u['last_login_at']?:'—')?><?=!empty($u['locked_until'])&&strtotime((string)$u['locked_until'])>time()?' · 🔒 قفل تا '.e($u['locked_until']):''?></div></div><form method="post" class="usergrid"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><label>نام نمایشی<input name="display_name" value="<?=e($u['display_name'])?>"></label><label>نقش<select name="role"><?php foreach(ts_roles() as $r):?><option value="<?=e($r)?>" <?=$u['role']===$r?'selected':''?>><?=e(ts_role_label($r))?></option><?php endforeach;?></select></label><label>فعال<input type="checkbox" name="active" value="1" <?=$u['active']?'checked':''?>></label><button class="btn">ذخیره دسترسی</button></form><form method="post" class="usergrid" style="margin-top:8px"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><label class="wide">رمز جدید<input type="password" name="password" minlength="12" placeholder="حداقل ۱۲ کاراکتر" autocomplete="new-password"></label><button class="btn pale">تغییر رمز + رفع قفل</button></form></div><?php endforeach;?></section><section class="panel"><h2>بکاپ خودکار</h2><?php if($backup):?><div class="success">آخرین بکاپ: <?=e($backup['finished_at']??'—')?> · دیتابیس: <?=e($backup['database_file']??'—')?><?=!empty($backup['uploads_file'])?' · تصاویر: '.e($backup['uploads_file']):''?></div><?php else:?><div class="notice">پس از اولین اجرای زمان‌بندی‌شده، وضعیت بکاپ اینجا نمایش داده می‌شود.</div><?php endif;?><p class="muted">دیتابیس هر شب نگهداری می‌شود و نسخه‌های قدیمی به‌صورت خودکار پاک می‌شوند. تصاویر محصولات نیز به‌صورت دوره‌ای آرشیو می‌شوند.</p></section><section class="panel logs"><h2>۳۰ رویداد امنیتی اخیر</h2><table><thead><tr><th>زمان</th><th>کاربر</th><th>رویداد</th><th>جزئیات</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['username']?:'—')?></td><td><?=e($l['action'])?></td><td><?=e($l['details'])?></td><td><?=e($l['ip'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>